// ===== SỬA 2 DÒNG NÀY RỒI LƯU =====
const CONFIG = {
  SECRET: 'DAN_N8N_SECRET_VAO_DAY' // trùng N8N_SECRET (chỉ dùng để kiểm tra lệnh "Chạy thử ngay" từ trang Admin)
};
// ===================================

const first = $input.first().json;
let items = [];
if (first.body && first.body.bundle) {
  // Lệnh "Chạy thử ngay" từ trang Admin FoodSave
  const headers = first.headers || {};
  if (CONFIG.SECRET && headers['x-n8n-secret'] !== CONFIG.SECRET) throw new Error('Sai mật khẩu x-n8n-secret');
  items = [{ post_log_id: first.body.post_log_id, ai: first.body.ai, page_id: first.body.page_id, ...first.body.bundle }];
} else {
  // Lịch chạy: FoodSave trả về danh sách bài tổng hợp
  const data = first.data || first;
  items = (data.items || []).map((it) => ({ ...it, ai: { enabled: data.ai_enabled !== false }, page_id: data.page_id }));
}
return items.map((json) => ({ json }));

// ===== SỬA CÁC DÒNG NÀY RỒI LƯU (không dán token vào chat hay Git) =====
const CONFIG = {
  API: 'https://foodsavevn.netlify.app/api/v1', // địa chỉ API của FoodSave (KHÔNG phải localhost khi dùng n8n Cloud)
  SECRET: 'DAN_N8N_SECRET_VAO_DAY',
  PAGE_ID: 'DAN_MA_FANPAGE_FOODSAVE',     // mã Fanpage trung tâm FoodSave (nếu FoodSave đã gửi page_id thì dùng giá trị đó)
  PAGE_TOKEN: 'DAN_TOKEN_VAO_DAY',        // token Fanpage trung tâm FoodSave
  OVERLAY: true
};
// =======================================================================

const bundle = $('Lặp từng bài').first().json;
const money = (n) => String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + 'đ';
const items = bundle.items || [];
const useAi = Boolean(bundle.ai && bundle.ai.enabled);
const linkOk = /^https:/.test(bundle.link || '');
const maxDiscount = Math.max(0, ...items.map((i) => Number(i.discount_percent) || 0));
const minPrice = Math.min(...items.map((i) => Number(i.price_vnd) || 0));
const earliest = items.slice().sort((a, b) => a.hours_left - b.hours_left)[0] || {};
const hasRed = items.some((i) => i.label === 'red');

const facts = items.map((i, n) => `${n + 1}. ${i.name} (cửa hàng ${i.store_name}): giảm ${i.discount_percent}%, giá mới ${money(i.price_vnd)}${Number(i.original_price_vnd) > Number(i.price_vnd) ? ', giá cũ ' + money(i.original_price_vnd) : ''}, lấy trước ${i.deadline_text}, nhãn ${i.label === 'red' ? 'ĐỎ (sắp hết)' : 'VÀNG'}`).join('\n');
const captionPrompt = [
  'Bạn quản lý Fanpage FoodSave, ứng dụng giải cứu thực phẩm gần hết hạn. Viết MỘT bài đăng Facebook tiếng Việt tổng hợp các món sau (từ nhiều cửa hàng khác nhau) để người mua biết đang có hàng cần mua trước khi hết hạn.',
  'DỮ KIỆN CỐ ĐỊNH (giữ nguyên từng con số và tên cửa hàng, KHÔNG sửa, thêm hay bịa):',
  facts,
  bundle.more_count > 0 ? `Ngoài ra còn ${bundle.more_count} món khác trên sàn (có thể nhắc "…và ${bundle.more_count} món khác").` : '',
  `Giọng điệu: ${hasRed ? 'khẩn trương nhưng thân thiện, nhắc giờ lấy cuối cùng' : 'nhẹ nhàng, giá mềm hôm nay'}.`,
  'Quy tắc: 6–8 dòng, emoji vừa phải, hashtag 3–5 cái (có #FoodSave). KHÔNG nhắc số lượng tồn kho. KHÔNG ghi "ảnh minh hoạ". Nêu khách tự đến cửa hàng nhận, không giao hàng.',
  linkOk ? `Gắn đúng một link: ${bundle.link}` : 'Không gắn link.',
  'Chỉ trả về nội dung bài đăng, không giải thích.'
].filter(Boolean).join('\n');

const imagePrompt = [
  'Tạo ảnh nền poster quảng cáo cho Fanpage FoodSave: bàn ăn với vài món đồ ăn hấp dẫn, tươi, màu sắc ấm.',
  hasRed ? 'Tông đỏ cam khẩn trương.' : 'Tông vàng ấm tươi sáng.',
  'Chừa trống khoảng 25% phía dưới và góc trên bên trái để chèn chữ sau.',
  'TUYỆT ĐỐI KHÔNG vẽ chữ, chữ số, logo hay watermark. Nếu có ảnh gốc đi kèm, lấy cảm hứng và giữ nhận diện món ăn.'
].join('\n');

const pageId = bundle.page_id || CONFIG.PAGE_ID;
return [{
  json: {
    mode: 'central',
    useAi,
    overlayEnabled: CONFIG.OVERLAY,
    label: hasRed ? 'red' : 'yellow',
    pageId,
    pageToken: CONFIG.PAGE_TOKEN,
    postLogId: bundle.post_log_id || null,
    callbackUrl: CONFIG.API + '/marketing/callback',
    secret: CONFIG.SECRET,
    imageUrl: bundle.hero_image_url || '',
    fallbackCaption: bundle.message,
    captionPrompt,
    imagePrompt,
    mustContain: items.map((i) => money(i.price_vnd)),
    link: linkOk ? bundle.link : '',
    overlay: {
      title: 'FOODSAVE · HÀNG SẮP HẾT HẠN',
      badge: `GIẢM TỚI ${maxDiscount}%`,
      line1: items.slice(0, 3).map((i) => i.name).join(' · '),
      line2: `Từ ${money(minPrice)} · lấy trước ${earliest.deadline_text || ''}`
    }
  }
}];

// Dựng yêu cầu gửi Gemini (caption + ảnh) và mã hóa ảnh gốc
// ===== TÊN MODEL GEMINI: chỉ sửa ở đây khi Google đổi tên (node Gemini đọc từ đây) =====
const CONFIG = {
  MODEL_TEXT: 'gemini-2.5-flash',        // viết caption
  MODEL_IMAGE: 'gemini-2.5-flash-image'  // tạo ảnh nền
};
// ==========================================================================================
const ctx = $('Chuẩn bị').first().json;
const item = $input.first();
let origB64 = '';
let mime = 'image/jpeg';
if (item.binary && item.binary.orig) {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'orig');
  origB64 = buf.toString('base64');
  mime = item.binary.orig.mimeType || mime;
}
const captionRequest = {
  contents: [{ parts: [{ text: ctx.captionPrompt }] }],
  generationConfig: { temperature: 0.6, maxOutputTokens: 600, thinkingConfig: { thinkingBudget: 0 } } // tắt "suy nghĩ" để caption không bị cắt
};
const imageParts = [{ text: ctx.imagePrompt }];
if (origB64) imageParts.unshift({ inline_data: { mime_type: mime, data: origB64 } });
const imageRequest = {
  contents: [{ parts: imageParts }],
  generationConfig: { responseModalities: ['IMAGE', 'TEXT'] }
};
return [{ json: { ...ctx, origB64, origMime: mime, captionRequest, imageRequest, modelText: CONFIG.MODEL_TEXT, modelImage: CONFIG.MODEL_IMAGE } }];

// Tầng 1 (AI): kiểm tra kết quả Gemini. Không đạt thì dùng caption mẫu (tầng 2). Ảnh AI chỉ dùng khi caption AI đạt.
const ctx = $('Dựng yêu cầu AI').first().json;
const capRes = $('Gemini · viết caption').first().json || {};
const imgRes = $('Gemini · tạo ảnh nền').first().json || {};

let caption = '';
let tier = 'template';
try {
  const text = capRes.candidates[0].content.parts.map((p) => p.text || '').join('').trim();
  const stockMention = /còn\s+\d+\s*(phần|suất|sản phẩm|món|cái|hộp)/i.test(text);
  const fakeTag = /minh\s*h[oọ]a/i.test(text);
  const hasNumbers = (ctx.mustContain || []).every((x) => text.includes(x));
  if (text.length > 30 && hasNumbers && !stockMention && !fakeTag) {
    caption = text;
    tier = 'ai';
  }
} catch (e) { /* dùng caption mẫu */ }
if (!caption) caption = ctx.fallbackCaption;
if (tier === 'ai' && ctx.link && !caption.includes(ctx.link)) caption += `\n👉 ${ctx.link}`;

let imgB64 = ctx.origB64 || '';
let mime = ctx.origMime || 'image/jpeg';
let aiImage = false;
if (tier === 'ai') {
  try {
    const parts = imgRes.candidates[0].content.parts;
    const part = parts.find((p) => p.inlineData || p.inline_data);
    const data = part && (part.inlineData || part.inline_data);
    if (data && data.data) { imgB64 = data.data; mime = data.mimeType || data.mime_type || 'image/png'; aiImage = true; }
  } catch (e) { /* giữ ảnh gốc */ }
}

const out = { json: { ...ctx, caption, tier, aiImage, imgB64, imgMime: mime } };
delete out.json.origB64; delete out.json.captionRequest; delete out.json.imageRequest;
if (imgB64) {
  out.binary = { data: await this.helpers.prepareBinaryData(Buffer.from(imgB64, 'base64'), aiImage ? 'poster.png' : 'goc.jpg', mime) };
}
return [out];

// Tầng 2 (mẫu): dùng caption mẫu của FoodSave + ảnh gốc, không gọi AI
const ctx = $('Dựng yêu cầu AI').first().json;
const out = { json: { ...ctx, caption: ctx.fallbackCaption, tier: 'template', aiImage: false, imgB64: ctx.origB64 || '', imgMime: ctx.origMime || 'image/jpeg' } };
delete out.json.origB64; delete out.json.captionRequest; delete out.json.imageRequest;
if (ctx.origB64) {
  out.binary = { data: await this.helpers.prepareBinaryData(Buffer.from(ctx.origB64, 'base64'), 'goc.jpg', ctx.origMime || 'image/jpeg') };
}
return [out];

// Chốt ảnh cuối cùng. Nếu bước chèn chữ lỗi (mất ảnh) thì dùng lại ảnh trước khi chèn chữ.
const src = $('Gộp kết quả AI').isExecuted ? $('Gộp kết quả AI').first().json : $('Dùng caption mẫu').first().json;
const item = $input.first();
const json = { ...src };
const b64 = json.imgB64;
delete json.imgB64;
let bin = item.binary && item.binary.data ? item.binary.data : null;
if (!bin && b64) {
  bin = await this.helpers.prepareBinaryData(Buffer.from(b64, 'base64'), 'poster.png', json.imgMime || 'image/png');
}
json.hasImage = Boolean(bin);
const out = { json };
if (bin) out.binary = { data: bin };
return [out];

// Gom kết quả đăng Facebook để báo về FoodSave
const c = $('Chốt ảnh').first().json;
const photo = $('Đăng ảnh lên Fanpage').isExecuted ? $('Đăng ảnh lên Fanpage').first().json : null;
const text = $('Đăng chữ lên Fanpage').isExecuted ? $('Đăng chữ lên Fanpage').first().json : null;
const res = text && text.id ? text : (photo && photo.id ? photo : null);
const ok = Boolean(res);
const pick = (r) => (r && r.error ? (r.error.message || JSON.stringify(r.error)) : '');
const error = ok ? '' : String(pick(text) || pick(photo) || 'Facebook từ chối bài đăng').slice(0, 400);
const id = ok ? String(res.post_id || res.id) : '';
return [{
  json: {
    post_log_id: c.postLogId,
    callbackUrl: c.callbackUrl,
    status: ok ? 'posted' : 'failed',
    tier: c.tier,
    external_id: id,
    external_url: ok ? 'https://www.facebook.com/' + id : '',
    error
  }
}];
